```js
const HASH_PATTERN = /\b(md5sum|sha1sum|sha256sum|sha512sum|shasum)\b|get-filehash|certutil\s+[^\n]*hashfile|\bhashlib\b|createhash\s*\(|crypto\.subtle\.digest|openssl\s+dgst/i;
```
