  return { name, status: r.status, stdout: r.stdout.trim(), stderr: r.stderr.trim() };
}

function checkSchema(out, label) {
  const obj = JSON.parse(out);
  for (const k of Object.keys(obj)) {
    if (!TOP_KEYS.has(k)) throw new Error(`${label}: 顶层多余 key "${k}"`);
  }
  if (!obj.hookSpecificOutput) throw new Error(`${label}: 缺 hookSpecificOutput`);
  for (const k of Object.keys(obj.hookSpecificOutput)) {
    if (!PRE_KEYS.has(k)) throw new Error(`${label}: 内层多余 key "${k}"`);
  }
  if (obj.hookSpecificOutput.hookEventName !== 'PreToolUse') throw new Error(`${label}: 事件名错`);
  if (typeof obj.hookSpecificOutput.additionalContext !== 'string' || !obj.hookSpecificOutput.additionalContext) {
    throw new Error(`${label}: additionalContext 非空字符串`);
  }
  if ('permissionDecision' in obj.hookSpecificOutput) throw new Error(`${label}: 不应有 permissionDecision`);
}

