1	#!/usr/bin/env node
2	'use strict';
3	
4	/*
5	 * no-overdefense PreToolUse 钩子（提醒式，不阻断）。
6	 * Bash 命令或写文件内容里出现哈希计算时，向对话注入一条提醒；
7	 * 每个会话最多提醒一次。任何异常都静默放行（fail-open）。
8	 *
9	 * 输出契约（ZCode PreToolUse 钩子，严格 schema，多余 key 会被拒收）：
10	 *   {"hookSpecificOutput":{"hookEventName":"PreToolUse","additionalContext":"..."}}
11	 * 不带 permissionDecision 即为默认放行；未命中时 stdout 留空、exit 0。
12	 */
13	
14	const fs = require('fs');
15	const os = require('os');
16	const path = require('path');
17	
18	// 只匹配哈希的实际调用（命令行工具或代码 API），不匹配纯文字提及。
19	const HASH_PATTERN = /\b(md5sum|sha1sum|sha256sum|sha512sum|shasum)\b|get-filehash|certutil[^\n]*hashfile|\bhashlib\b|createhash\s*\(|crypto\.subtle\.digest|openssl\s+dgst/i;
20	
21	const BASH_MESSAGE = '过度防御提醒：检测到哈希计算。如果目的是对比文件是否相同或确认改动，直接用 diff、比较文件大小或看文件名即可；哈希只在任务确实要求防篡改或一致性校验时使用，而且不需要对每个文件逐个计算。如果本次计算确实是必要的，忽略本提醒。';
22	
23	const WRITE_MESSAGE = '过度防御提醒：新写入的代码里包含哈希计算。请确认这段校验有真实用途（任务要求的完整性或一致性校验，且结果会被实际使用）；如果确实是必要的，忽略本提醒。';
24	
25	function readStdin() {
26	  return new Promise((resolve) => {
27	    let body = '';
28	    process.stdin.setEncoding('utf8');
29	    process.stdin.on('data', (chunk) => { body += chunk; });
30	    process.stdin.on('end', () => resolve(body));
31	    process.stdin.on('error', () => resolve(''));
32	  });
33	}
34	
35	function reminderText(toolName, input) {
36	  if (toolName === 'Bash') {
37	    return HASH_PATTERN.test(String(input.command || '')) ? BASH_MESSAGE : null;
38	  }
39	  if (toolName === 'Write') {
40	    return HASH_PATTERN.test(String(input.content || '')) ? WRITE_MESSAGE : null;
